mapper.select:
SELECT s.*, ii.country ii_country,ii.provider ii_provider, ii.city ii_city ,ii.asnumber ii_asnumber,ii.isp ii_isp, ii.province ii_province,ii.zipcode ii_zipcode,ii.district ii_district, dt.type dnsType,v.`vulnerability` v_vulnerability FROM (select s.* from scan_result s
s.ip = #{params.ip}
order by s.time desc LIMIT #{params.n},#{params.m} ) s LEFT JOIN ip_information ii ON ii.ip = s.ip LEFT JOIN dns_type dt ON dt.ip = s.ip AND dt.`epoch` = s.`epoch` LEFT JOIN `vulnerability` v ON v.`component` = s.`component`

SELECT TYPE,COUNT(distinct ip) count FROM (
SELECT s.ip,dt.type FROM `scan_result` s
JOIN `dns_type` dt ON s.ip=dt.ip
where type IS NOT NULL AND type !=''

    and s.ip = #{params.ip}


    and dt.type = #{params.dnsType}

) a1
GROUP BY a1.type

SELECT ii.`province`,COUNT(distinct s.ip) count FROM `scan_result` s JOIN `ip_information` ii ON s.ip = ii.ip AND ii.province IS NOT NULL AND ii.province !=''
and s.ip = #{params.ip}
GROUP BY ii.province

SELECT ii.`provider`,COUNT(s.ip) count FROM `scan_result` s JOIN `ip_information` ii ON s.ip = ii.ip AND provider IS NOT NULL AND provider !=''
s.ip = #{params.ip}
GROUP BY ii.provider

SELECT s.component,COUNT(distinct s.ip) count FROM `scan_result` s where component IS NOT NULL AND component !=''
and s.ip = #{params.ip}
GROUP BY s.component

SELECT vulnerability,COUNT(ip) count FROM ( SELECT s.ip ,v.`vulnerability` FROM `scan_result` s JOIN `vulnerability` v ON v.`component` = s.`component` where vulnerability IS NOT NULL AND vulnerability !=''
and s.ip = #{params.ip}
) a1 GROUP BY a1.vulnerability

select count(1) from
(select id,ip,epoch from scan_result sr


        sr.ip = #{params.ip}


) sc
join ( select d.id,d.ip,d.epoch from dns_type d where d.type = #{dnsType}) dt
on dt.ip = sc.ip AND dt.epoch = sc.epoch

select count(distinct sc.ip)
from ( select id,ip,epoch from scan_result sr


        ip = #{params.ip}


) sc
join (select ip, epoch from dns_type d where d.type = #{dnsType})
dt on dt.ip = sc.ip and dt.epoch = sc.epoch

 select count(1) count
 from (
       select da.ip
          from (select count(1), d.ip from doh_attribute d


                 d.ip = #{params.ip}


                 and d.`port` = #{params.port}


       group by d.ip) da
       JOIN scan_result s on da.ip = s.ip
      ) dip
join scan_result sc on sc.ip = dip.ip

SELECT sc.*, ii.country ii_country, ii.provider ii_provider, ii.city ii_city, ii.asnumber ii_asnumber, ii.isp ii_isp, ii.province ii_province,ii.zipcode ii_zipcode, ii.district ii_district, dt.type dnsType, v.`vulnerability` v_vulnerability from ( select da.ip from (select count(1), d.ip from doh_attribute d
d.ip = #{params.ip}
and d.`port` = #{params.port}
group by d.ip) da JOIN scan_result s on da.ip = s.ip ) dip
join scan_result sc on sc.ip = dip.ip left join ip_information ii on ii.ip = dip.ip left join vulnerability v on v.component = sc.component left join dns_type dt ON dt.ip = sc.ip AND dt.`epoch` = sc.`epoch` order by sc.`time` desc LIMIT #{params.offset},#{params.limit}

SELECT dt.type, COUNT(distinct da.ip) count
FROM (select count(1),d.ip from doh_attribute d


        d.ip = #{params.ip}


        and d.`port` = #{params.port}


group by d.ip
) da
JOIN scan_result s on da.ip = s.ip
JOIN `dns_type` dt ON da.ip = dt.ip and dt.type > 0

GROUP BY dt.type

select s.`province`,COUNT(distinct s.ip) count  from
     (SELECT  s.ip,ii.province   FROM `scan_result` s
            JOIN `ip_information` ii  ON s.ip = ii.ip
            where ii.province IS NOT NULL AND ii.province !=''

                AND s.ip = #{params.ip}

         ) s
    join dns_type dt on s.ip = dt.ip
where dt.type = #{dnsType}
GROUP BY s.province

SELECT s.`provider`,COUNT(distinct s.ip) count FROM ( SELECT ii.`provider`,s.ip FROM `scan_result` s JOIN `ip_information` ii ON s.ip = ii.ip AND provider IS NOT NULL AND provider !=''
s.ip = #{params.ip}
) s JOIN dns_type dt on dt.ip = s.ip
AND dt.type = #{dnsType}
GROUP BY s.provider

select s.component,COUNT(distinct s.ip) count
from (
    SELECT s.component, s.ip  FROM `scan_result` s
where
component IS NOT NULL AND component !=''

    and s.ip = #{params.ip}

) s
JOIN (SELECT ip from dns_type where type = #{dnsType}) dt on s.ip = dt.ip
GROUP BY s.component

SELECT COUNT(a1.ip) count FROM (
SELECT s.ip,dt.type FROM `scan_result` s
JOIN `dns_type` dt ON s.ip=dt.ip
where dt.type = #{dnsType}

    and s.ip = #{params.ip}

) a1
GROUP BY a1.type

SELECT vulnerability,COUNT(a1.ip) count FROM (
SELECT s.ip
,v.`vulnerability`
FROM `scan_result` s
JOIN `vulnerability` v ON v.`component` = s.`component`
where vulnerability IS NOT NULL AND vulnerability !=''

    and s.ip = #{params.ip}

) a1
JOIN dns_type dt on a1.ip = dt.ip and dt.type = #{dnsType}
GROUP BY a1.vulnerability
